import { expect, test } from '../fixtures';

/** A value that is new on every run (an email, a name), so a second run does not collide with the first. */
function makeUnique(): (base: string) => string {
  const seen = new Map<string, string>();
  return (base) => {
    const known = seen.get(base);
    if (known) return known;
    const tag = Math.random().toString(36).slice(2, 8);
    const at = base.indexOf('@');
    const value = at === -1 ? `${base}-${tag}` : `${base.slice(0, at)}+${tag}${base.slice(at)}`;
    seen.set(base, value);
    return value;
  };
}

// Starts signed out, whatever session the rest of the suite shares.
test.use({ storageState: { cookies: [], origins: [] } });

test('Register new user', async ({ page }) => {
  const unique = makeUnique();

  await test.step('Open the register page', async () => {
    await page.goto('/register');
  });

  await test.step('Type a new name', async () => {
    await page.getByRole('textbox', { name: 'User Name', exact: true }).fill('sova-newuser');
  });

  await test.step('Type an email', async () => {
    await page.getByRole('textbox', { name: 'Email', exact: true }).fill(unique('sova-newuser@example.com'));
  });

  await test.step('Type a password', async () => {
    await page.getByRole('textbox', { name: 'Password', exact: true }).fill('secret-pass-123');
  });

  await test.step('Press Submit', async () => {
    await page.getByRole('button', { name: 'Submit', exact: true }).click();
  });

  await test.step('The challenges page opens', async () => {
    await expect(page).toHaveURL(/\/challenges/);
  });
});
